import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int q = nextInt();
        ArrayDeque<String> incoming = new ArrayDeque<>(), outgoing = new ArrayDeque<>(); // two stacks
        StringJoiner out = new StringJoiner(" ");
        for (int i = 0; i < q; i++) {
            String op = next();
            if (op.equals("push")) {
                incoming.push(next());
                out.add("null");
            } else if (op.equals("empty")) {
                out.add(incoming.isEmpty() && outgoing.isEmpty() ? "true" : "false");
            } else {
                // refill only when the outgoing stack is empty, reversing the order
                if (outgoing.isEmpty())
                    while (!incoming.isEmpty()) outgoing.push(incoming.pop());
                out.add(op.equals("pop") ? outgoing.pop() : outgoing.peek());
            }
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var q int
	fmt.Fscan(in, &q)
	var incoming, outgoing, out []string // two stacks
	for i := 0; i < q; i++ {
		var op string
		fmt.Fscan(in, &op)
		switch op {
		case "push":
			var x string
			fmt.Fscan(in, &x)
			incoming = append(incoming, x)
			out = append(out, "null")
		case "empty":
			if len(incoming) == 0 && len(outgoing) == 0 {
				out = append(out, "true")
			} else {
				out = append(out, "false")
			}
		default:
			// refill only when the outgoing stack is empty, reversing the order
			if len(outgoing) == 0 {
				for len(incoming) > 0 {
					outgoing = append(outgoing, incoming[len(incoming)-1])
					incoming = incoming[:len(incoming)-1]
				}
			}
			out = append(out, outgoing[len(outgoing)-1])
			if op == "pop" {
				outgoing = outgoing[:len(outgoing)-1]
			}
		}
	}
	fmt.Println(strings.Join(out, " "))
}
